  1	package queue;
  2	
  3	import java.util.AbstractQueue;
  4	import java.util.Arrays;
  5	import java.util.ConcurrentModificationException;
  6	import java.util.Iterator;
  7	import java.util.NoSuchElementException;
  8	import java.util.Objects;
  9	
 10	public final class CircularQueue<T> extends AbstractQueue<T> {
 11	
 12	    private static final String EMPTY_QUEUE_MESSAGE = "Queue is empty.";
 13	    private static final String FULL_QUEUE_MESSAGE = "Queue is full.";
 14	
 15	    private final Object[] elements;
 16	    private int head;
 17	    private int tail;
 18	    private int size;
 19	    private int modificationCount;
 20	
 21	    public CircularQueue(int capacity) {
 22	        if (capacity <= 0) {
 23	            throw new IllegalArgumentException("Capacity must be positive.");
 24	        }
 25	
 26	        elements = new Object[capacity];
 27	        resetState();
 28	    }
 29	
 30	    public void enqueue(T value) {
 31	        if (!offer(value)) {
 32	            throw new IllegalStateException(FULL_QUEUE_MESSAGE);
 33	        }
 34	    }
 35	
 36	    public T dequeue() {
 37	        requireNotEmpty();
 38	        T removedValue = removeHead();
 39	        modificationCount++;
 40	        return removedValue;
 41	    }
 42	
 43	    public T peekFront() {
 44	        requireNotEmpty();
 45	        return elementAt(head);
 46	    }
 47	
 48	    public T peekRear() {
 49	        requireNotEmpty();
 50	        return elementAt(indexFromHead(size - 1));
 51	    }
 52	
 53	    public T getFront() {
 54	        return peekFront();
 55	    }
 56	
 57	    public T getRear() {
 58	        return peekRear();
 59	    }
 60	
 61	    public boolean isEmpty() {
 62	        return size == 0;
 63	    }
 64	
 65	    public boolean isFull() {
 66	        return size == elements.length;
 67	    }
 68	
 69	    @Override
 70	    public boolean offer(T value) {
 71	        Objects.requireNonNull(value, "Queue elements must be non-null.");
 72	
 73	        if (isFull()) {
 74	            return false;
 75	        }
 76	
 77	        insertAtTail(value);
 78	        modificationCount++;
 79	        return true;
 80	    }
 81	
 82	    @Override
 83	    public T poll() {
 84	        if (isEmpty()) {
 85	            return null;
 86	        }
 87	
 88	        T removedValue = removeHead();
 89	        modificationCount++;
 90	        return removedValue;
 91	    }
 92	
 93	    @Override
 94	    public T peek() {
 95	        if (isEmpty()) {
 96	            return null;
 97	        }
 98	        return elementAt(head);
 99	    }
100	
101	    @Override
102	    public int size() {
103	        return size;
104	    }
105	
106	    public int capacity() {
107	        return elements.length;
108	    }
109	
110	    public int remainingCapacity() {
111	        return capacity() - size;
112	    }
113	
114	    @Override
115	    public void clear() {
116	        Arrays.fill(elements, null);
117	        resetState();
118	        modificationCount++;
119	    }
120	
121	    @Override
122	    public Iterator<T> iterator() {
123	        return new QueueIterator();
124	    }
125	
126	    @Override
127	    public String toString() {
128	        StringBuilder builder = new StringBuilder();
129	        builder.append('[');
130	
131	        for (int offset = 0; offset < size; offset++) {
132	            if (offset > 0) {
133	                builder.append(", ");
134	            }
135	
136	            builder.append(elementAt(indexFromHead(offset)));
137	        }
138	
139	        builder.append(']');
140	        return builder.toString();
141	    }
142	
143	    private int advance(int index) {
144	        return (index + 1) % elements.length;
145	    }
146	
147	    private int indexFromHead(int offset) {
148	        return (head + offset) % elements.length;
149	    }
150	
151	    private void resetState() {
152	        head = 0;
153	        tail = 0;
154	        size = 0;
155	    }
156	
157	    private void requireNotEmpty() {
158	        if (isEmpty()) {
159	            throw new IllegalStateException(EMPTY_QUEUE_MESSAGE);
160	        }
161	    }
162	
163	    private void insertAtTail(T value) {
164	        elements[tail] = value;
165	        tail = advance(tail);
166	        size++;
167	    }
168	
169	    private T removeHead() {
170	        T removedValue = elementAt(head);
171	        elements[head] = null;
172	        head = advance(head);
173	        size--;
174	        return removedValue;
175	    }
176	
177	    @SuppressWarnings("unchecked")
178	    private T elementAt(int index) {
179	        return (T) elements[index];
180	    }
181	
182	    private final class QueueIterator implements Iterator<T> {
183	        private final int expectedModificationCount = modificationCount;
184	        private int offset;
185	
186	        @Override
187	        public boolean hasNext() {
188	            ensureUnmodified();
189	            return offset < size;
190	        }
191	
192	        @Override
193	        public T next() {
194	            ensureUnmodified();
195	            if (offset >= size) {
196	                throw new NoSuchElementException();
197	            }
198	
199	            T value = elementAt(indexFromHead(offset));
200	            offset++;
201	            return value;
202	        }
203	
204	        private void ensureUnmodified() {
205	            if (expectedModificationCount != modificationCount) {
206	                throw new ConcurrentModificationException();
207	            }
208	        }
209	    }
210	}
